import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.BVA38fkC.js";var i=JSON.parse(`{"title":"Getting started","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/docs/guide/getting-started.html"}],["meta",{"property":"og:title","content":"Getting started | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/docs/guide/getting-started.html"}],["meta",{"name":"twitter:title","content":"Getting started | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1794147699000}`),a={name:`guide/getting-started.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting started”">​</a></h1><p>FD Cal has two entry points: the browser application for interactive scenarios and the Node.js CLI for development, diagnostics and automated workflows.</p><h2 id="use-the-web-application" tabindex="-1">Use the web application <a class="header-anchor" href="#use-the-web-application" aria-label="Permalink to “Use the web application”">​</a></h2><p>Open the <a href="https://aaron-fredrick.github.io/FD-Calculator/web/" target="_blank" rel="noreferrer">FD Cal web application</a>. The browser runs the shared JavaScript calculation engine in a background worker, keeping the page responsive during expensive optimisation. A scenario draft is saved locally in this browser; account data is not uploaded.</p><h2 id="configure-a-scenario" tabindex="-1">Configure a scenario <a class="header-anchor" href="#configure-a-scenario" aria-label="Permalink to “Configure a scenario”">​</a></h2><p>The web configurator follows four stages:</p><ol><li><strong>Investment window</strong> — set the start and end dates. Deposits that cannot mature within the selected window are excluded.</li><li><strong>Bank accounts</strong> — select the banks and enter only the amount allocated to this plan, not the full bank-account balance. Choose the consolidation account that receives the portfolio&#39;s remaining cash for final valuation. This is not an executable transfer.</li><li><strong>Cash-flow plans</strong> — add recurring or date-specific inflows and outflows. Specific dates use <code>YYYY-MM-DD</code>, separated by commas, and must fall within the investment window. Outflow policies mean: <ul><li><strong>Strict:</strong> the simulation is invalid if the account cannot pay the full amount.</li><li><strong>Defer:</strong> carry the unpaid amount forward.</li><li><strong>Best effort:</strong> pay what is available and carry any remainder forward.</li></ul></li><li><strong>Strategy and assumptions</strong> — choose a supported strategy, review transfer-fee defaults, age-segmented product inclusion, AIT, compounding and leap-year assumptions.</li></ol><p>The senior/minor switches add products with bank-published age conditions to the candidate set. They do not verify a depositor&#39;s age or guarantee eligibility. Where a booked product has catalogue age/guardian conditions, the standalone report displays those conditions for manual bank verification.</p><h2 id="choose-a-strategy" tabindex="-1">Choose a strategy <a class="header-anchor" href="#choose-a-strategy" aria-label="Permalink to “Choose a strategy”">​</a></h2><p>The web application exposes <strong>Greedy</strong>, <strong>Absolute R+</strong> and <strong>GSS</strong> for scoped date-range simulations. <strong>Absolute R</strong> is CLI-only. Goal mode is under development and disabled; use the feature-request link beside the unavailable mode to suggest or discuss the planned capability.</p><ul><li><strong>Greedy</strong> — fast local decisions; useful as a baseline, but it does not guarantee the best full-horizon result.</li><li><strong>Absolute R+</strong> — bounded beam search over multiple promising plans. Search limits trade exploration against runtime; pruning or a decision cap can prevent a global-optimality proof.</li><li><strong>GSS</strong> — recursive scoped planning with liquidity-aware SPLIT and CONSOLIDATE evaluation. It is a heuristic, not an exhaustive optimality proof.</li><li><strong>Absolute R</strong> — exhaustive branch-and-bound search; CLI only.</li></ul><p>Read the <a href="/FD-Calculator/docs/STRATEGIES.html">strategy guide</a> before comparing results. Outcomes depend on the supplied data, assumptions and simulation horizon.</p><h2 id="understand-the-result" tabindex="-1">Understand the result <a class="header-anchor" href="#understand-the-result" aria-label="Permalink to “Understand the result”">​</a></h2><p>The in-app result is deliberately concise: gross interest, AIT withheld, transfer fees, net interest, final value and capital invested. It is not intended to duplicate the full event history.</p><p>Use <strong>Download HTML report</strong> or <strong>Open report</strong> for the full inspection record: selected FD bookings, account movements, cash-flow schedules, maturities, performance charts and the event ledger. The generated HTML report is standalone and can be opened offline without fetching external fonts, scripts or chart assets.</p><p>The report may contain account labels, opening balances, selected deposits and a full event history. Treat it as a private financial document when saving or sharing it. Its catalogue fingerprint identifies the bank/product and fee snapshot used; the generated timestamp comes from the local device clock.</p><h2 id="data-and-assumptions" tabindex="-1">Data and assumptions <a class="header-anchor" href="#data-and-assumptions" aria-label="Permalink to “Data and assumptions”">​</a></h2><p>FD Cal uses its configured bank/product data and financial assumptions. Product annual rates are nominal terms; portfolio-level annualised money-weighted return reflects the timing of deposits and withdrawals. Verify current rates, fees, eligibility and tax treatment with the relevant bank or authority before acting on a result. FD Cal is a planning tool, not financial or tax advice.</p><h2 id="run-locally" tabindex="-1">Run locally <a class="header-anchor" href="#run-locally" aria-label="Permalink to “Run locally”">​</a></h2><h3 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h3><ul><li>Node.js 22 or newer</li><li>npm</li></ul><h3 id="install-and-test" tabindex="-1">Install and test <a class="header-anchor" href="#install-and-test" aria-label="Permalink to “Install and test”">​</a></h3><p>Clone the repository, then run:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>Run the CLI help:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><h3 id="configure-a-cli-scenario" tabindex="-1">Configure a CLI scenario <a class="header-anchor" href="#configure-a-cli-scenario" aria-label="Permalink to “Configure a CLI scenario”">​</a></h3><p>Copy the example configuration before editing it:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.json.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.json</span></span></code></pre></div><p>The local <code>config.json</code> is ignored by Git because it may contain private financial information. Do not commit real account details or personal financial records.</p>`,30)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};